begin read only;
with objects as(select c.*,n.nspname,r.rolname owner from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.oid=c.relowner where n.nspname='public' and c.relkind in('r','p')),
inventory as(select o.nspname schema,o.relname table_name,o.owner,g.rolname beneficiary,grantor.rolname grantor,a.privilege_type,a.is_grantable,o.relrowsecurity rls,a.grantee=o.relowner owner_entry, o.relacl is not null explicit_object_acl,has_table_privilege(g.oid,o.oid,'TRUNCATE') effective_truncate,has_schema_privilege(g.oid,o.relnamespace,'USAGE') schema_usage,pg_has_role(g.oid,o.relowner,'MEMBER') owner_membership from objects o cross join lateral aclexplode(coalesce(o.relacl,acldefault('r',o.relowner))) a join pg_roles g on g.oid=a.grantee left join pg_roles grantor on grantor.oid=a.grantor where a.privilege_type='TRUNCATE' and g.rolname in('anon','authenticated')),
defaults as(select r.rolname owner,coalesce(n.nspname,'GLOBAL') schema,coalesce(g.rolname,'PUBLIC') beneficiary,gr.rolname grantor,a.privilege_type,a.is_grantable from pg_default_acl d join pg_roles r on r.oid=d.defaclrole left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a left join pg_roles g on g.oid=a.grantee left join pg_roles gr on gr.oid=a.grantor where d.defaclobjtype='r' and a.privilege_type='TRUNCATE'),
roles as(select rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls from pg_roles),
memberships as(select member.rolname member,parent.rolname role,grantor.rolname grantor,m.admin_option,m.inherit_option,m.set_option from pg_auth_members m join pg_roles member on member.oid=m.member join pg_roles parent on parent.oid=m.roleid join pg_roles grantor on grantor.oid=m.grantor),
settings as(select coalesce(r.rolname,'ALL') role,coalesce(d.datname,'ALL') db,split_part(v,'=',1) name,substring(v from position('=' in v)+1) value from pg_db_role_setting s left join pg_roles r on r.oid=s.setrole left join pg_database d on d.oid=s.setdatabase cross join lateral unnest(s.setconfig) v where split_part(v,'=',1) in('pgrst.db_schemas','pgrst.db_pre_request','pgrst.db_extra_search_path','pgrst.db_pre_config'))
select jsonb_build_object('version',current_setting('server_version'),'actor',current_user,'inventory',(select jsonb_agg(to_jsonb(i) order by table_name,beneficiary) from inventory i),'defaults',(select jsonb_agg(to_jsonb(d) order by owner,schema,beneficiary) from defaults d),'roles',(select jsonb_agg(to_jsonb(r) order by rolname) from roles r),'memberships',(select jsonb_agg(to_jsonb(m) order by member,role) from memberships m),'api_settings',(select jsonb_agg(to_jsonb(s)) from settings s)) audit;rollback;
